using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned metadata for: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// 2a. Default resolver knows about Person → succeeds
if (options.TryGetTypeInfo<Person>(out var info))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {info!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> returned false");

// 2b. A source-gen context that only declares Widget — Person is NOT resolvable
var limited = new JsonSerializerOptions { TypeInfoResolver = WidgetContext.Default };

if (limited.TryGetTypeInfo<Person>(out _))
    Console.WriteLine("TryGetTypeInfo<Person> on limited context: found (unexpected)");
else
    Console.WriteLine("TryGetTypeInfo<Person> on limited context: not available — no exception thrown");

if (limited.TryGetTypeInfo<Widget>(out var widgetInfo))
    Console.WriteLine($"TryGetTypeInfo<Widget> on limited context: found {widgetInfo!.Type.Name}");

public record Person(string Name, int Age);
public record Widget(string Id);

[JsonSerializable(typeof(Widget))]
public partial class WidgetContext : JsonSerializerContext;

